#!/usr/bin/env node
/**
 * Case generators for the differential harness. Each generator prints JSON
 * lines on stdout; pick one with `node gen.mjs <suite> [count] [seed]`.
 */

const PRINTABLE = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i));

/** Deterministic xorshift PRNG so runs are reproducible. */
function rng(seed) {
  let state = seed | 0 || 0x2545f491;
  return () => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    return ((state >>> 0) % 1_000_000_007) / 1_000_000_007;
  };
}

const emit = (name, args, env) =>
  console.log(JSON.stringify(env ? { name, args, env } : { name, args }));

const pick = (random, pool) => pool[Math.floor(random() * pool.length)];
const str = (random, length, pool) =>
  Array.from({ length }, () => pick(random, pool)).join('');

const suites = {
  /** Random printable-ASCII 16-byte keys and data — the happy path. */
  ascii(count, seed) {
    const random = rng(seed);
    for (let i = 0; i < count; i += 1) {
      emit(`ascii#${i}`, [
        '--key',
        str(random, 16, PRINTABLE),
        '--data',
        str(random, 16, PRINTABLE),
      ]);
    }
  },

  /** Every byte value 0x20..0x7e in every position, to stress repr escaping. */
  reprSweep() {
    const key = 'yPcJ.h9oOX7e5!cV';
    for (let byte = 0x20; byte < 0x7f; byte += 1) {
      const char = String.fromCharCode(byte);
      emit(`repr-lead-${byte}`, ['--key', key, '--data', char.repeat(16)]);
      emit(`repr-mixed-${byte}`, ['--key', key, '--data', `abc${char}def"gh'ij`.slice(0, 16)]);
    }
    // Quote combinations drive repr's delimiter choice.
    for (const data of [
      "aaaaaaaaaaaaaaa'",
      'aaaaaaaaaaaaaaa"',
      'aaaaaaa\'aaaaaaa"',
      "''''''''''''''''",
      '""""""""""""""""',
      '\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\',
      "'\"\\'\"\\'\"\\'\"\\'\"\\a",
    ]) {
      emit(`repr-quotes-${data.length}-${data.slice(0, 3)}`, ['--key', key, '--data', data]);
    }
  },

  /** Control characters and DEL, which repr renders as \t \n \r or \xNN. */
  controlBytes() {
    const key = 'yPcJ.h9oOX7e5!cV';
    for (let byte = 0; byte < 0x20; byte += 1) {
      if (byte === 0) continue; // a NUL cannot be passed through execve
      const hex = byte.toString(16).padStart(2, '0');
      emit(`ctrl-${hex}`, [
        '--key',
        key,
        '--data',
        { raw: `\\x${hex}`.repeat(16) },
      ]);
      emit(`ctrl-mixed-${hex}`, [
        '--key',
        key,
        '--data',
        { raw: `abcde\\x${hex}fghijklmn` },
      ]);
    }
    emit('ctrl-7f', ['--key', key, '--data', { raw: '\\x7f'.repeat(16) }]);
    emit('ctrl-high', ['--key', key, '--data', { raw: '\\xc3\\xa9'.repeat(8) }]);
  },

  /** Random 24- and 32-byte keys (AES-192 / AES-256). */
  keySizes(count, seed) {
    const random = rng(seed);
    for (let i = 0; i < count; i += 1) {
      for (const size of [16, 24, 32]) {
        emit(`key${size}#${i}`, [
          '--key',
          str(random, size, PRINTABLE),
          '--data',
          str(random, 16, PRINTABLE),
        ]);
      }
    }
  },

  /** Key and data lengths around every boundary, valid and invalid. */
  lengths() {
    const pad = (n) => 'k'.repeat(n);
    for (let keyLength = 0; keyLength <= 40; keyLength += 1) {
      emit(`keylen-${keyLength}`, ['--key', pad(keyLength), '--data', pad(16)]);
    }
    for (let dataLength = 0; dataLength <= 40; dataLength += 1) {
      emit(`datalen-${dataLength}`, ['--key', pad(16), '--data', pad(dataLength)]);
    }
