  unicode() {
    const key = 'yPcJ.h9oOX7e5!cV';
    const samples = [
      'é'.repeat(8), // 16 bytes
      'é'.repeat(7), // 14 bytes
      'é'.repeat(9), // 18 bytes
      '€'.repeat(5) + 'a', // 16 bytes
      '€'.repeat(5), // 15 bytes
      '𝄞'.repeat(4), // 16 bytes
      '𝄞'.repeat(3) + 'abcd', // 16 bytes
      'ünïcödé tëst 1', // 20 bytes
      '日本語テキスト', // 21 bytes
      '日本語です' + 'a', // 16 bytes
      'ÿ'.repeat(8), // 16 bytes
      '￿' + 'abcdefghijklm', // 16 bytes
      '�'.repeat(5) + 'a', // 16 bytes: a genuine replacement char
