      emit(`raw-len14#${i}`, ['--key', key, '--data', { raw: `abcdefghijklmn${sequence}` }]);
    }
  },

  /** Command-line parsing: abbreviations, `=`, `--`, unknown options, help. */
  argparse() {
    const key = 'yPcJ.h9oOX7e5!cV';
    const data = '=b=M1F[g)],C0CZ6';
