#!/usr/bin/env node
/**
 * High-volume randomized stress generator for the test13 differential harness.
 *
 * node /tmp/stress.mjs <suite> [count] [seed]
 *
 * Suites:
 *   asciiRandom   random printable-ASCII 16-byte key + data
 *   keySizes      random 16/24/32-byte keys (and near-miss sizes)
 *   utf8Exact     random multi-byte UTF-8 strings encoding to exactly 16 bytes
 *   utf8Off       same but off-by-one/two from 16 bytes
 *   rawSoup       random raw byte sequences (valid + invalid UTF-8)
 *   tokenSoup     random argparse token soups
 *   columnsSoup   random COLUMNS values against help/usage/error paths
 *   mixed         weighted blend of all of the above
 */

const PRINTABLE = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i));

/** mulberry32 - decent distribution, deterministic. */
function rng(seed) {
  let a = (seed >>> 0) || 0x9e3779b9;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const out = [];
const emit = (name, args, env) =>
  out.push(JSON.stringify(env ? { name, args, env } : { name, args }));

const pick = (r, pool) => pool[Math.floor(r() * pool.length)];
const int = (r, lo, hi) => lo + Math.floor(r() * (hi - lo + 1));
const str = (r, n, pool) => Array.from({ length: n }, () => pick(r, pool)).join('');

const KEY16 = 'yPcJ.h9oOX7e5!cV';

/** Random code point with a given UTF-8 encoded byte width. */
function cpOfWidth(r, width) {
  if (width === 1) return int(r, 0x20, 0x7e);
  if (width === 2) return int(r, 0x80, 0x7ff);
  if (width === 3) {
    for (;;) {
      const cp = int(r, 0x800, 0xffff);
      if (cp < 0xd800 || cp > 0xdfff) return cp;
    }
  }
  return int(r, 0x10000, 0x10ffff);
}

/** Build a JS string whose UTF-8 encoding is exactly `target` bytes. */
function utf8OfLength(r, target) {
  let remaining = target;
  let s = '';
  while (remaining > 0) {
    const choices = [1, 2, 3, 4].filter((w) => w <= remaining);
    // Bias away from 1-byte so we get genuinely multi-byte strings.
    const widths = remaining >= 2 ? choices.filter((w) => w > 1).concat(choices) : choices;
    const w = pick(r, widths);
    s += String.fromCodePoint(cpOfWidth(r, w));
    remaining -= w;
  }
  return s;
}

/** Escape a byte array into a bash $'...' body. */
const rawOf = (bytes) => bytes.map((b) => `\\x${b.toString(16).padStart(2, '0')}`).join('');

/** Random byte sequence, never containing NUL (execve can't carry it). */
function randomBytes(r, n, mode) {
  const bytes = [];
  for (let i = 0; i < n; i += 1) {
    if (mode === 'high') bytes.push(int(r, 0x80, 0xff));
    else if (mode === 'ctrl') bytes.push(int(r, 1, 0x1f));
    else bytes.push(int(r, 1, 0xff));
  }
  return bytes;
}

const BAD_UTF8 = [
  [0xff], [0xfe], [0x80], [0xbf], [0xc0, 0x80], [0xc1, 0xbf],
  [0xe0, 0x80, 0x80], [0xed, 0xa0, 0x80], [0xed, 0xbf, 0xbf],
  [0xf5, 0x80, 0x80, 0x80], [0xf8, 0x88, 0x80, 0x80, 0x80],
  [0xc3], [0xe1, 0x80], [0xf0, 0x9f], [0xf0, 0x9f, 0x98],
  [0xc3, 0xa9, 0xff], [0xff, 0xfe, 0xfd], [0x80, 0x80, 0x80],
  [0xe2, 0x82], [0xf4, 0x90, 0x80, 0x80], [0xf7, 0xbf, 0xbf, 0xbf],
];

const suites = {
  asciiRandom(n, seed) {
    const r = rng(seed);
    for (let i = 0; i < n; i += 1) {
      emit(`ascii#${i}`, ['--key', str(r, 16, PRINTABLE), '--data', str(r, 16, PRINTABLE)]);
    }
  },

  keySizes(n, seed) {
    const r = rng(seed);
    const sizes = [15, 16, 17, 23, 24, 25, 31, 32, 33];
    for (let i = 0; i < n; i += 1) {
      const size = pick(r, sizes);
      emit(`ks${size}#${i}`, [
        '--key', str(r, size, PRINTABLE),
        '--data', str(r, 16, PRINTABLE),
      ]);
    }
  },

  utf8Exact(n, seed) {
    const r = rng(seed);
    for (let i = 0; i < n; i += 1) {
      const which = int(r, 0, 2);
      const data = utf8OfLength(r, 16);
      const key = utf8OfLength(r, pick(r, [16, 24, 32]));
      if (which === 0) emit(`u16d#${i}`, ['--key', KEY16, '--data', data]);
      else if (which === 1) emit(`u16k#${i}`, ['--key', key, '--data', str(r, 16, PRINTABLE)]);
      else emit(`u16kd#${i}`, ['--key', key, '--data', data]);
    }
  },

  utf8Off(n, seed) {
    const r = rng(seed);
    for (let i = 0; i < n; i += 1) {
      const dlen = pick(r, [13, 14, 15, 17, 18, 19]);
      const klen = pick(r, [14, 15, 17, 18, 22, 23, 25, 30, 31, 33, 34]);
      const which = int(r, 0, 1);
      if (which === 0) emit(`uoffd#${i}`, ['--key', KEY16, '--data', utf8OfLength(r, dlen)]);
      else emit(`uoffk#${i}`, ['--key', utf8OfLength(r, klen), '--data', str(r, 16, PRINTABLE)]);
    }
  },

  rawSoup(n, seed) {
    const r = rng(seed);
    for (let i = 0; i < n; i += 1) {
      const kind = int(r, 0, 4);
      if (kind === 0) {
        // Pure random bytes, length around 16.
        const len = pick(r, [13, 14, 15, 16, 17, 18]);
        emit(`rawd#${i}`, [
          '--key', KEY16,
          '--data', { raw: rawOf(randomBytes(r, len, pick(r, ['any', 'high', 'ctrl']))) },
        ]);
      } else if (kind === 1) {
        const len = pick(r, [16, 24, 32, 15, 17]);
        emit(`rawk#${i}`, [
          '--key', { raw: rawOf(randomBytes(r, len, pick(r, ['any', 'high', 'ctrl']))) },
          '--data', str(r, 16, PRINTABLE),
        ]);
      } else if (kind === 2) {
        // Insert a known-bad UTF-8 sequence at a random offset in ASCII filler.
        const bad = pick(r, BAD_UTF8);
        const total = pick(r, [16, 15, 17, 14, 18, 13]);
        const fillLen = Math.max(0, total - bad.length);
        const at = int(r, 0, fillLen);
        const fill = Array.from({ length: fillLen }, () => int(r, 0x21, 0x7e));
        const bytes = [...fill.slice(0, at), ...bad, ...fill.slice(at)];
        emit(`badd#${i}`, ['--key', KEY16, '--data', { raw: rawOf(bytes) }]);
      } else if (kind === 3) {
        const bad = pick(r, BAD_UTF8);
        const total = pick(r, [16, 24, 32]);
        const fillLen = Math.max(0, total - bad.length);
        const at = int(r, 0, fillLen);
        const fill = Array.from({ length: fillLen }, () => int(r, 0x21, 0x7e));
        const bytes = [...fill.slice(0, at), ...bad, ...fill.slice(at)];
        emit(`badk#${i}`, [
          '--key', { raw: rawOf(bytes) },
          '--data', str(r, 16, PRINTABLE),
        ]);
      } else {
        // Both raw.
        const dl = pick(r, [16, 15, 17]);
        const kl = pick(r, [16, 24, 32]);
        emit(`rawboth#${i}`, [
          '--key', { raw: rawOf(randomBytes(r, kl, 'any')) },
          '--data', { raw: rawOf(randomBytes(r, dl, 'any')) },
        ]);
      }
    }
  },

  tokenSoup(n, seed) {
    const r = rng(seed);
    const keyAbbrev = ['--key', '--ke', '--k', '--KEY', '-key', '-k', '---key', '--key='];
    const dataAbbrev = ['--data', '--dat', '--da', '--d', '--DATA', '-data', '-d', '---data', '--data='];
    const junk = [
      '--foo', '-x', '-hx', 'extra', '--', '-', '--help', '-h', '--=x', '--help=x',
      '--h', '--he', '', '-1', '-1.5', '--key', '--data', '=', 'a=b', '--foo=bar',
      '-abc', '--data=', '--key=', '@file', '--é', '--datax', '--keyy',
    ];
    const values = [
      KEY16, '=b=M1F[g)],C0CZ6', '-notanoption', '-1234567890123456', '',
      '-', '--', 'aaaaaaaaaaaaaaaa', '-h', '--help', 'short', '-12ab567890123456',
      '-ab cd efghijklm', 'x'.repeat(24), 'x'.repeat(32),
    ];
    for (let i = 0; i < n; i += 1) {
      const tokens = [];
      const nTok = int(r, 0, 7);
      for (let t = 0; t < nTok; t += 1) {
        const kind = int(r, 0, 9);
        if (kind <= 2) {
          const flag = pick(r, keyAbbrev);
          const val = pick(r, values);
          if (flag.endsWith('=')) tokens.push(flag + val);
          else if (r() < 0.35) tokens.push(`${flag}=${val}`);
          else { tokens.push(flag); if (r() < 0.85) tokens.push(val); }
        } else if (kind <= 5) {
          const flag = pick(r, dataAbbrev);
          const val = pick(r, values);
          if (flag.endsWith('=')) tokens.push(flag + val);
          else if (r() < 0.35) tokens.push(`${flag}=${val}`);
          else { tokens.push(flag); if (r() < 0.85) tokens.push(val); }
        } else if (kind <= 7) {
          tokens.push(pick(r, junk));
        } else {
          tokens.push(pick(r, values));
        }
      }
      if (r() < 0.25) {
        emit(`tok#${i}`, tokens, { COLUMNS: String(pick(r, [10, 20, 40, 60, 80, 120, 200])) });
      } else {
        emit(`tok#${i}`, tokens);
      }
    }
  },

  columnsSoup(n, seed) {
    const r = rng(seed);
    const argSets = [
      ['--help'],
      [],
      ['--key', KEY16],
      ['--data', 'aaaaaaaaaaaaaaaa'],
      ['--key', KEY16, '--nope'],
      ['--key', KEY16, '--data', 'aaaaaaaaaaaaaaaa', 'extra'],
      ['--k'],
      ['--key', KEY16, '--data'],
      ['-h'],
      ['--key', KEY16, '--data', 'aaaaaaaaaaaaaaaa'],
    ];
    for (let i = 0; i < n; i += 1) {
      const cols = pick(r, [
        String(int(r, 1, 300)), String(int(r, 1, 300)), '0', '1', '2', '3', '-1',
        'abc', '', ' 40 ', '80x', '1e3', '9999999', '000040', '+50', '40.5',
      ]);
      emit(`cols#${i}`, pick(r, argSets), { COLUMNS: cols });
    }
  },

  mixed(n, seed) {
    const r = rng(seed);
    const parts = ['asciiRandom', 'keySizes', 'utf8Exact', 'utf8Off', 'rawSoup', 'tokenSoup', 'columnsSoup'];
    const per = Math.ceil(n / parts.length);
    for (const [i, p] of parts.entries()) suites[p](per, seed + i * 7919 + Math.floor(r() * 1000));
  },
};

const [suite, count = '500', seed = '1'] = process.argv.slice(2);
if (!(suite in suites)) {
  console.error(`unknown suite: ${suite}\navailable: ${Object.keys(suites).join(', ')}`);
  process.exit(2);
}
suites[suite](Number(count), Number(seed));
process.stdout.write(out.join('\n') + '\n');

