    report.push(`  got  out : ${JSON.stringify(actual.stdout)}`);
  }
  if (problems.includes('stderr')) {
    report.push(`  want err : ${JSON.stringify(normalise(expected.stderr))}`);
    report.push(`  got  err : ${JSON.stringify(normalise(actual.stderr))}`);
  }
  return report.join('\n');
}

const cases = readFileSync(casesPath, 'utf8')
  .split('\n')
  .filter((line) => line.trim() !== '')
  .map((line) => JSON.parse(line));

let failures = 0;
let next = 0;
const maxReports = Number(option('--max-reports', '2000'));

async function worker() {
