#!/usr/bin/env node
/** Additional stress suites: lengths, long args, error-text rendering. */
const PRINTABLE = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i));
function rng(seed) {
  let a = (seed >>> 0) || 0x9e3779b9;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const out = [];
const emit = (name, args, env) => out.push(JSON.stringify(env ? { name, args, env } : { name, args }));
const pick = (r, p) => p[Math.floor(r() * p.length)];
const int = (r, lo, hi) => lo + Math.floor(r() * (hi - lo + 1));
const str = (r, n, p) => Array.from({ length: n }, () => pick(r, p)).join('');
const KEY16 = 'yPcJ.h9oOX7e5!cV';

const suites = {
  /** Exhaustive key/data byte lengths, random content, plus large sizes. */
  allLengths(n, seed) {
    const r = rng(seed);
    for (let L = 0; L <= 64; L += 1) {
      emit(`klen-${L}`, ['--key', str(r, L, PRINTABLE), '--data', str(r, 16, PRINTABLE)]);
      emit(`dlen-${L}`, ['--key', KEY16, '--data', str(r, L, PRINTABLE)]);
      emit(`kdlen-${L}`, ['--key', str(r, L, PRINTABLE), '--data', str(r, L, PRINTABLE)]);
    }
    for (const L of [100, 127, 128, 255, 256, 257, 512, 1000, 1024, 4095, 4096, 8192]) {
      emit(`kbig-${L}`, ['--key', str(r, L, PRINTABLE), '--data', str(r, 16, PRINTABLE)]);
      emit(`dbig-${L}`, ['--key', KEY16, '--data', str(r, L, PRINTABLE)]);
    }
  },

  /** Values that land inside error/usage text. */
  errorText(n, seed) {
    const r = rng(seed);
    const ESC = String.fromCharCode(27);
    const nasty = [
      'a\nb', 'a\tb', '%s', '%d', '%%', '{}', '{0}', '{key}', '$PATH', '\\n', '\r\n',
      '-'.repeat(40), 'x'.repeat(120), '…'.repeat(20), '日本語'.repeat(10),
      'a'.repeat(300), '--key', '--data', '-h', '--help', '', '   ',
      `${ESC}[31mred${ESC}[0m`, 'bell', 'tab\there', 'nl\nhere\nagain',
    ];
    for (let i = 0; i < n; i += 1) {
      const v = pick(r, nasty);
      const shape = int(r, 0, 5);
      const cols = pick(r, [null, '20', '40', '60', '80', '200', String(int(r, 5, 120))]);
      const env = cols ? { COLUMNS: cols } : undefined;
      if (shape === 0) emit(`et-unrec#${i}`, ['--key', KEY16, '--data', 'aaaaaaaaaaaaaaaa', v], env);
      else if (shape === 1) emit(`et-badopt#${i}`, ['--key', KEY16, `--${v}`], env);
      else if (shape === 2) emit(`et-keyval#${i}`, ['--key', v, '--data', 'aaaaaaaaaaaaaaaa'], env);
      else if (shape === 3) emit(`et-dataval#${i}`, ['--key', KEY16, '--data', v], env);
      else if (shape === 4) emit(`et-missing#${i}`, [v], env);
      else emit(`et-eq#${i}`, [`--key=${v}`, `--data=${v}`], env);
    }
  },

  /** Deep token soups: many tokens, repeated flags, interleaved junk. */
  deepSoup(n, seed) {
    const r = rng(seed);
    const flags = [
      '--key', '--data', '--k', '--d', '--ke', '--da', '--dat', '-h', '--help',
      '--', '-', '---', '--key=', '--data=', '--KEY', '--Data', '-key', '-data',
      '--foo', '--bar=1', '--kеy', '--–key',
    ];
    const vals = [
      KEY16, 'aaaaaaaaaaaaaaaa', 'short', '', '-x', '--y', '=z', 'a=b',
      'x'.repeat(24), 'x'.repeat(32), '-16bytes-value-x', 'é'.repeat(8),
    ];
    for (let i = 0; i < n; i += 1) {
      const tokens = [];
      const nTok = int(r, 0, 14);
      for (let t = 0; t < nTok; t += 1) tokens.push(r() < 0.5 ? pick(r, flags) : pick(r, vals));
      emit(`deep#${i}`, tokens, r() < 0.3 ? { COLUMNS: String(int(r, 8, 140)) } : undefined);
    }
  },

  /** Raw bytes in option names, =values, unrecognized tokens, dash-values. */
  rawFlags(n, seed) {
    const r = rng(seed);
    const rawOf = (b) => b.map((x) => `\\x${x.toString(16).padStart(2, '0')}`).join('');
    const bads = [0xff, 0xfe, 0x80, 0xc0, 0xed, 0xa0, 0xf5, 0xc3, 0xe1, 0x9f];
    for (let i = 0; i < n; i += 1) {
      const kind = int(r, 0, 4);
      const bad = pick(r, bads);
      if (kind === 0) {
        emit(`rf-opt#${i}`, [{ raw: `--k${rawOf([bad])}ey` }, KEY16, '--data', 'aaaaaaaaaaaaaaaa']);
      } else if (kind === 1) {
        emit(`rf-eq#${i}`, [
          { raw: `--key=${rawOf(Array.from({ length: 16 }, () => int(r, 1, 255)))}` },
          '--data', 'aaaaaaaaaaaaaaaa',
        ]);
      } else if (kind === 2) {
        emit(`rf-unrec#${i}`, [
          '--key', KEY16, '--data', 'aaaaaaaaaaaaaaaa',
          { raw: rawOf(Array.from({ length: int(r, 1, 8) }, () => int(r, 1, 255))) },
        ]);
      } else if (kind === 3) {
        emit(`rf-dash#${i}`, [
          '--key', KEY16, '--data',
          { raw: `-${rawOf(Array.from({ length: 16 }, () => int(r, 1, 255)))}` },
        ]);
      } else {
        emit(`rf-abbrev#${i}`, [
          { raw: `--${rawOf([bad])}` }, '--key', KEY16, '--data', 'aaaaaaaaaaaaaaaa',
        ]);
      }
    }
  },
};
const [suite, count = '500', seed = '1'] = process.argv.slice(2);
if (!(suite in suites)) {
  console.error(`unknown suite: ${suite}\navailable: ${Object.keys(suites).join(', ')}`);
  process.exit(2);
}
suites[suite](Number(count), Number(seed));
process.stdout.write(out.join('\n') + '\n');

